        if (this.items.has(itemName)) {
            this.items.set(itemName, this.items.get(itemName) + quantity);
        }
        else {
            this.items.set(itemName, quantity);
        }
        return `${quantity} ${itemName}(s) added to ${this.name}'s inventory.`;
    }

    removeItem(itemName, quantity) {
        // TODO: Move this method's core logic to the new Inventory class
        // TODO: Add input validation: quantity must be a positive integer
        if (!this.items.has(itemName)) {
            return `${itemName} not found in ${this.name}'s inventory.`;
        }

        let currentQuantity = this.items.get(itemName);
        if (currentQuantity <= quantity) {
            this.items.delete(itemName);
            return `All ${itemName}(s) removed from ${this.name}'s inventory.`;
        }
        else {
            this.items.set(itemName, currentQuantity - quantity);
            return `${quantity} ${itemName}(s) removed from ${this.name}'s inventory.`;
        }
    }

    listItems() {
        // TODO: Move this method's core logic to the new Inventory class
        if (this.items.size === 0) {
            return `${this.name}'s inventory is empty.`;
        }
        let itemStrings = [];
        for (let [item, quantity] of this.items) {
            itemStrings.push(`${item} x${quantity}`);
        }
        return `${this.name}'s inventory: ${itemStrings.join(', ')}.`;
    }
}

