class Inventory {
    #items;

    constructor() {
        this.#items = new Map(); // Stores items: {itemName: quantity}
    }

    addItem(itemName, quantity) {
        if (typeof quantity !== 'number' || !Number.isInteger(quantity) || quantity <= 0) {
            return `Invalid quantity for '${itemName}'. Must be a positive integer.`;
        }
        const currentQuantity = this.#items.get(itemName) || 0;
        this.#items.set(itemName, currentQuantity + quantity);
        return `${quantity} ${itemName}(s) added to inventory.`;
    }

    removeItem(itemName, quantity) {
        if (typeof quantity !== 'number' || !Number.isInteger(quantity) || quantity <= 0) {
            return `Invalid quantity for '${itemName}'. Must be a positive integer.`;
        }
        if (!this.#items.has(itemName)) {
            return `'${itemName}' not found in inventory.`;
        }

        let currentQuantity = this.#items.get(itemName);
        if (currentQuantity < quantity) {
            return `Not enough '${itemName}' to remove. Only ${currentQuantity} available.`;
        }
        else if (currentQuantity === quantity) {
            this.#items.delete(itemName);
            return `All '${itemName}' (x${quantity}) removed from inventory.`;
        }
        else {
            this.#items.set(itemName, currentQuantity - quantity);
            return `${quantity} '${itemName}'(s) removed from inventory.`;
        }
    }

    listItems() {
        if (this.#items.size === 0) {
            return `inventory is empty.`;
        }
        const itemStrings = [];
        for (const [item, quantity] of this.#items) {
            itemStrings.push(`${item} x${quantity}`);
        }
        return `inventory: ${itemStrings.join(', ')}.`;
    }
}

